import { render } from '@solidjs/web';
import { onSettled } from 'solid-js';

function App() {
  let input;
  // Focus the input once it is connected to the document.
  return (
    <>
      <h1>Focus after render</h1>
      <label>
        Your name <input ref={input} placeholder="Ready for typing" />
      </label>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

import { render } from '@solidjs/web';
import { onSettled } from 'solid-js';

function App() {
  let input;
  onSettled(() => input.focus());
  return (
    <>
      <h1>Focus after render</h1>
      <label>
        Your name <input ref={input} placeholder="Ready for typing" />
      </label>
    </>
  );
}

render(() => <App />, document.getElementById('app'));
